CREATE TABLE stops (
    id TEXT PRIMARY KEY NOT NULL,
    name TEXT NOT NULL,
    locality TEXT,
    letter TEXT,
    towards TEXT,
    stop_code TEXT,
    stop_area_id TEXT,
    lat REAL NOT NULL,
    lon REAL NOT NULL,
    bearing TEXT,
    is_hail_and_ride INTEGER NOT NULL,
    routes TEXT NOT NULL
);
CREATE INDEX stops_location ON stops (lat, lon);
CREATE INDEX stops_stop_code ON stops (stop_code);
BEGIN TRANSACTION;
COMMIT;
